$ ./gradlew run

{"base":"KRW","date":"2026-09-09","rates":{"USD":0.00072,"EUR":0.00066}}

#   알았다

#   rates.USD 가 0.00072 다
#   date 필드가 있다
#   base 를 에코해 준다

#   이 코드는 지운다

# --- 이제 TDD 가 된다 ---

@DisplayName("환율이 주어지면 원화를 달러로 바꾼다")
@Test
void convertToUsd() {
    ExchangeRate rate = new ExchangeRate("KRW", "USD", 0.00072);

    double usd = ExchangeCalculator.convert(10000, rate);

    assertThat(usd).isEqualTo(7.2, within(0.001));
}

$ ./gradlew test --tests ExchangeCalculatorTest

> Task :compileTestJava FAILED
ExchangeCalculatorTest.java:12: error: cannot find symbol
        double usd = ExchangeCalculator.convert(10000, rate);

#   빨강이다. 정상적인 TDD 사이클이다

#   API 호출은 분리했다
#   계산은 순수 함수다  (2.7절)

# --- 학습 테스트로 남기면 ---

@DisplayName("환율 API 응답에는 rates 맵이 들어 있다")
@Test
void exchangeApiResponse() {
    String body = "{\"base\":\"KRW\",\"date\":\"2026-09-09\","
            + "\"rates\":{\"USD\":0.00072}}";

    ExchangeResponse response = objectMapper.readValue(body, ExchangeResponse.class);

    assertThat(response.getBase()).isEqualTo("KRW");
    assertThat(response.getRates()).containsKey("USD");
}

$ ./gradlew test --tests ExchangeApiLearningTest

ExchangeApiLearningTest > 환율 API 응답에는 rates 맵이 들어 있다 PASSED

#   응답 형식이 문서로 남았다

#   API 가 바뀌면 이 테스트가 안 깨진다 (하드코딩된 문자열이라)
#   그래서 계약 테스트는 따로 필요하다

#   9.1절에서 다룬다

# --- 성능은 어떤가 ---

@Test
void 백만_건_계산이_1초_안에_끝난다() {
    List<Beverage> beverages = IntStream.range(0, 1_000_000)
            .mapToObj(i -> new Americano())
            .collect(toList());
    Order order = new Order(beverages);

    long start = System.nanoTime();
    order.calculateTotalPrice();
    long elapsed = (System.nanoTime() - start) / 1_000_000;

    assertThat(elapsed).isLessThan(1000);
}

